package ultra.downloads;
import java.util.*;import java.io.*;
/** A loaded native response is usable as a full batch only when its own shelf is exhausted. */
public final class NativeSnapshot {
 static final class Snapshot {ArrayList<Catalog.Track> tracks=new ArrayList<>();boolean complete;String reason="unknown";}
 static final Map<String,Snapshot> cache=new LinkedHashMap<>();
 static String key(String id){return id!=null&&id.startsWith("VL")?id.substring(2):id;}
 static byte[] findShelf(byte[] b,int start,int end,int depth,int[] budget)throws Exception{if(depth>28||--budget[0]<0)return null;List<OfflineCommands.Part> parts;try{parts=OfflineCommands.fields(b,start,end);}catch(IOException e){return null;}byte[] found=null;for(OfflineCommands.Part p:parts){byte[] child;if(p.field==175617300)child=Arrays.copyOfRange(b,p.start,p.end);else child=findShelf(b,p.start,p.end,depth+1,budget);if(child!=null){if(found!=null)throw new IOException("Multiple playlist shelves");found=child;}}return found;}
 public static void accept(String browse,byte[] bytes){if(browse==null||bytes==null||bytes.length>12*1024*1024)return;try{playlistHeaders(bytes,0,new int[]{40000});Snapshot s=parse(browse,bytes);if(s==null)return;synchronized(cache){cache.put(key(browse),s);while(cache.size()>4)cache.remove(cache.keySet().iterator().next());}PlaylistIndex.record(browse,s.tracks,s.complete);Diagnostics.event("native_snapshot",(s.complete?"complete-":"partial-")+s.tracks.size());}catch(Throwable e){Diagnostics.error("native_snapshot",e);}}
 public static void playlistHeaders(byte[] bytes){if(bytes!=null&&bytes.length<=12*1024*1024)playlistHeaders(bytes,0,new int[]{40000});}
 static void playlistHeaders(byte[] b,int depth,int[] budget){if(b==null||depth>32||--budget[0]<0)return;try{List<OfflineCommands.Part> fs=OfflineCommands.fields(b,0,b.length);for(OfflineCommands.Part p:fs)if(p.field==361650780){byte[] header=Arrays.copyOfRange(b,p.start,p.end);String id=text(OfflineCommands.one(header,5),0),name=text(OfflineCommands.one(header,4),0);if(id.matches("PL[A-Za-z0-9_-]{2,198}")&&!name.isEmpty())PlaylistIndex.register("VL"+id,name,image(header,0));}for(OfflineCommands.Part p:fs)playlistHeaders(Arrays.copyOfRange(b,p.start,p.end),depth+1,budget);}catch(Exception ignored){}}
 static String image(byte[] b,int d){if(b==null||d>12)return "";String v=new String(b,java.nio.charset.StandardCharsets.UTF_8);if(v.startsWith("https://")&&(v.contains("ytimg.com/")||v.contains("googleusercontent.com/")))return v;try{for(OfflineCommands.Part p:OfflineCommands.fields(b,0,b.length)){String n=image(Arrays.copyOfRange(b,p.start,p.end),d+1);if(!n.isEmpty())return n;}}catch(Exception ignored){}return "";}
 static Snapshot parse(String browse,byte[] bytes)throws Exception{byte[] shelf=findShelf(bytes,0,bytes.length,0,new int[]{20000});if(shelf==null)return null;byte[] id=OfflineCommands.one(shelf,1);if(id==null||!key(browse).equals(new String(id,"UTF-8")))throw new IOException("Playlist identity differs");Snapshot out=new Snapshot();out.complete=true;Set<String> seen=new HashSet<>();for(OfflineCommands.Part p:OfflineCommands.fields(shelf,0,shelf.length)){if(p.field==10){out.complete=false;out.reason="continuation-remains";}if(p.field!=3)continue;byte[] wrapper=Arrays.copyOfRange(shelf,p.start,p.end),row=OfflineCommands.one(wrapper,161429595);if(row==null){out.complete=false;out.reason="unsupported-row";continue;}byte[] nav=OfflineCommands.one(row,5),watch=nav==null?null:OfflineCommands.one(nav,48687757),video=watch==null?null:OfflineCommands.one(watch,1);String v=video==null?"":new String(video,"UTF-8");if(!v.matches("[A-Za-z0-9_-]{11}")){out.complete=false;out.reason="unavailable-row";continue;}String title=text(OfflineCommands.one(row,3),0),artist=text(OfflineCommands.one(row,4),0);int bullet=artist.indexOf(" • ");if(bullet>=0)artist=artist.substring(0,bullet);out.tracks.add(new Catalog.Track(v,title.isEmpty()?v:title,artist,""));}if(out.tracks.isEmpty()){out.complete=false;out.reason="empty";}if(out.complete)out.reason="exhausted";return out;}
 static String text(byte[] b,int depth)throws Exception{if(b==null||depth>5)return "";StringBuilder result=new StringBuilder();try{for(OfflineCommands.Part p:OfflineCommands.fields(b,0,b.length))if(p.field==1){byte[] child=Arrays.copyOfRange(b,p.start,p.end);String inner=text(child,depth+1);if(inner.isEmpty()){inner=new String(child,"UTF-8");if(inner.indexOf('\0')>=0||inner.indexOf('\n')>=0)inner="";}result.append(inner);}}catch(IOException ignored){}return result.toString();}
 static ArrayList<Catalog.Track> complete(String id){synchronized(cache){Snapshot s=cache.get(key(id));return s!=null&&s.complete?new ArrayList<>(s.tracks):null;}}
 static ArrayList<Catalog.Track> loaded(String id){synchronized(cache){Snapshot s=cache.get(key(id));return s==null?null:new ArrayList<>(s.tracks);}}
 static Snapshot get(String id){synchronized(cache){return cache.get(key(id));}}
}
